steps.cmd:
cd /tmp && cat > an.py <<'EOF'
import json, datetime as dt
from zoneinfo import ZoneInfo
from collections import Counter, defaultdict
pages=json.load(open("pages.json"))
# check overlap
for i in range(1,len(pages)):
    if pages[i][0]!=pages[i-1][-1]: print("overlap mismatch page",i,pages[i-1][-1],pages[i][0])
allr=[r for p in pages for r in p]
print(Counter(r["v"] for r in allr), Counter(tuple(sorted(r)) for r in allr))
def norm(r):
    if r["v"]==1:
        t=dt.datetime.fromisoformat(r["ts"]); 
        if t.tzinfo is None: t=t.replace(tzinfo=dt.timezone.utc)
        return t, r["kwh"]
    return dt.datetime.fromtimestamp(r["ts"]/1000,dt.timezone.utc), r["wh"]/1000 if r.get("wh") is not None else None
rows=[(norm(r),r) for r in allr]
by=defaultdict(list)
for (t,k),r in rows: by[t].append((k,r))
dups={t:v for t,v in by.items() if len(v)>1}
print("unique ts",len(by),"dup ts",len(dups))
for t,v in list(dups.items())[:20]: print(t,v)
ts=sorted(by)
print(ts[0],ts[-1])
for a,b in zip(ts,ts[1:]):
    if b-a!=dt.timedelta(hours=1): print("gap",a,b)
# order check
prev=None
for (t,k),r in rows:
    if prev and t<prev: print("out of order",prev,t)
    prev=t
vals=[k for (t,k),r in rows]
print("none/neg", [ (t,k) for (t,k),r in rows if k is None or k<0][:10])
# first v2
for (t,k),r in rows:
    if r["v"]==2: print("first v2",t,r);break
EOF
python3 an.py

