cd /app; cat > /tmp/an.py <<'EOF'
import json
from datetime import datetime, timezone, timedelta
from zoneinfo import ZoneInfo
pages=json.load(open("/tmp/pages.json"))
raw=[]
for i,p in enumerate(pages):
    for j,r in enumerate(p["records"]):
        raw.append((i,j,r))
print("pages",len(pages),"raw",len(raw))
from collections import Counter
print(Counter(r.get("v") for _,_,r in raw), Counter(tuple(sorted(r)) for _,_,r in raw))
def norm(r):
    if r["v"]==1:
        t=datetime.fromisoformat(r["ts"]); 
        if t.tzinfo is None: t=t.replace(tzinfo=timezone.utc)
        return t, r["kwh"]
    return datetime.fromtimestamp(r["ts"]/1000,timezone.utc), r["wh"]/1000
recs={}
dups=Counter(); conflicts=[]
prev=None
for i,j,r in raw:
    t,k=norm(r)
    if t in recs:
        dups[(i,j)]+=1
        if abs(recs[t]-k)>1e-9: conflicts.append((t,recs[t],k,i,j))
    else: recs[t]=k
    if prev and t<prev and j!=0: print("out of order",t,prev)
    prev=t
print("dups",len(dups),"conflicts",conflicts[:10])
# non-first-of-page dups
print([d for d in dups if d[1]!=0][:10])
ts=sorted(recs); print(ts[0],ts[-1],len(ts))
for a,b in zip(ts,ts[1:]):
    if b-a!=timedelta(hours=1): print("gap",a,b)
# v switch
vs=[(norm(r)[0],r["v"]) for _,_,r in raw]
for a,b in zip(vs,vs[1:]):
    if a[1]!=b[1]: print("vswitch",a,b)
tz=ZoneInfo("America/Los_Angeles")
vals=[recs[t] for t in ts]
neg=[(t,recs[t]) for t in ts if recs[t]<=0 or recs[t]>200]
print("odd",neg[:20])
json.dump({t.isoformat():recs[t] for t in ts},open("/tmp/recs.json","w"))
EOF
python3 /tmp/an.py

