ts=sorted(d)
print(ts[0],ts[-1],len(ts))
for a,b in zip(ts,ts[1:]):
    if b-a!=timedelta(hours=1): print("gap",a,b)
# versions switch
prev=None
for t,e,r in rows:
    if r["v"]!=prev: print("v",r["v"],"at",t,r); prev=r["v"]
odd=[(t,e) for t in ts for e in [d[t][0][0]] if e<0 or e>100]
print("odd",odd[:20])
json.dump([(t.isoformat(),d[t][0][0]) for t in ts],open("series.json","w"))
EOF
