cd /tmp; cat > an.py <<'EOF'
import json, datetime as dt
from zoneinfo import ZoneInfo
LA=ZoneInfo("America/Los_Angeles"); UTC=dt.timezone.utc
pages=json.load(open("pages.json"))
recs=[]
for i,p in enumerate(pages):
    # check overlap
    if i>0: print("page",i,"first==prev last:", p[0]==pages[i-1][-1], p[0], pages[i-1][-1]) if p[0]!=pages[i-1][-1] else None
    recs += p if i==0 else p[1:]
norm=[]
for r in recs:
    if r["v"]==1:
        t=dt.datetime.fromisoformat(r["ts"]); t=t.replace(tzinfo=UTC) if t.tzinfo is None else t.astimezone(UTC); e=r["kwh"]
    else:
        t=dt.datetime.fromtimestamp(r["ts"]/1000,UTC); e=r["wh"]/1000
    norm.append((t,e,r))
print(len(norm), norm[0][0], norm[-1][0])
from collections import Counter
c=Counter(t for t,_,_ in norm); print("dups", [(k,v) for k,v in c.items() if v>1])
for a,b in zip(norm,norm[1:]):
    d=(b[0]-a[0]).total_seconds()
    if d!=3600: print("gap/order", a[0], b[0], d, a[2], b[2])
# version switch
for a,b in zip(norm,norm[1:]):
    if a[2]["v"]!=b[2]["v"]: print("vswitch",a[2],b[2], a[0].astimezone(LA))
# odd values
for t,e,r in norm:
    if e is None or e<0 or e>100: print("odd",t.astimezone(LA),r)
json.dump([(t.isoformat(),e) for t,e,_ in norm],open("norm.json","w"))
EOF
