import json,subprocess,time,sys
from datetime import datetime,timezone,timedelta
from zoneinfo import ZoneInfo

METER='M-1001'
TZ='America/Los_Angeles'

def meterctl_readings(cursor=None, limit=100):
    cmd=['meterctl','readings','--meter',METER,'--limit',str(limit)]
    if cursor is not None:
        cmd += ['--cursor', str(cursor)]
    while True:
        p=subprocess.run(cmd,capture_output=True,text=True)
        if p.returncode==3:
            data=json.loads(p.stdout)
            time.sleep(data.get('retry_after_s',1))
            continue
        if p.returncode!=0:
            raise RuntimeError(f"meterctl failed rc={p.returncode} stdout={p.stdout} stderr={p.stderr}")
        return json.loads(p.stdout)

def iter_unique_records():
    cursor=None
    prev_key=None
    while True:
        page=meterctl_readings(cursor=cursor, limit=100)
        for r in page['records']:
            if r.get('v')==1:
                ts=datetime.fromisoformat(r['ts']).replace(tzinfo=timezone.utc)
                kwh=float(r['kwh'])
            elif r.get('v')==2:
                ts=datetime.fromtimestamp(r['ts']/1000, tz=timezone.utc)
                kwh=float(r['wh'])/1000.0
            else:
                continue
            key=(ts,kwh,r.get('v'))
            if key==prev_key:
                continue
            prev_key=key
            yield ts,kwh,r.get('v')
        cursor=page['next_cursor']
        if not page['has_more']:
            break

def main():
    flags=[]
    la=ZoneInfo(TZ)
    start_utc=datetime(2026,11,1,0,0,0,tzinfo=la).astimezone(timezone.utc)
    end_utc=datetime(2026,12,1,0,0,0,tzinfo=la).astimezone(timezone.utc)

    sel=[]
    versions=set()
    for ts,kwh,v in iter_unique_records():
        if start_utc < ts <= end_utc:
            sel.append((ts,kwh))
            versions.add(v)

    if not sel:
        out={"status":"cannot_determine","reason":"no records found in target month","flags":["no_data"]}
        open('/app/answer.json','w').write(json.dumps(out))
        return

    sel.sort(key=lambda x:x[0])
    # Expect 721 hours in Nov 2026 LA due to DST end (extra hour)
    expected_hours=721
    if len(sel)!=expected_hours:
        flags.append(f"unexpected_hour_count:{len(sel)}")

    # detect gaps
    gaps=0
    for (t1,_),(t2,_) in zip(sel, sel[1:]):
        dt=t2-t1
        if dt!=timedelta(hours=1):
            gaps += max(0,int(dt/timedelta(hours=1))-1)
    if gaps:
        flags.append(f"gaps_hours:{gaps}")

    if len(versions)>1:
        flags.append("mixed_record_versions")

    total=sum(kwh for _,kwh in sel)
    out={"answer": total, "flags": flags}
    open('/app/answer.json','w').write(json.dumps(out))

if __name__=='__main__':
    main()
