        p.check_returncode();
        return json.loads(p.stdout)

def iter_records():
    cursor=None; last=None
    while True:
        d=call(cursor)
        recs=d['records']
        if last is not None and recs and recs[0]==last:
            recs=recs[1:]
        for r in recs:
            yield r; last=r
        if not d['has_more']:
            break
        cursor=d['next_cursor']

la=ZoneInfo('America/Los_Angeles')
start=datetime.datetime(2026,11,1,0,0,tzinfo=la).astimezone(datetime.timezone.utc)
end=datetime.datetime(2026,12,1,0,0,tzinfo=la).astimezone(datetime.timezone.utc)

s=0.0
for r in iter_records():
    if r['v']==1:
        ts=datetime.datetime.fromisoformat(r['ts']).replace(tzinfo=datetime.timezone.utc)
        val=r['kwh']
    else:
        ts=datetime.datetime.fromtimestamp(r['ts']/1000, tz=datetime.timezone.utc)
        val=r['wh']/1000
    if start < ts <= end:
        s+=val
print(f"{s:.6f}")
