import json, subprocess, time, sys
from datetime import datetime, timezone
from zoneinfo import ZoneInfo

METER='M-1001'
TZ=ZoneInfo('America/Los_Angeles')
start_local=datetime(2026,11,1,0,0,0,tzinfo=TZ)
end_local=datetime(2026,12,1,0,0,0,tzinfo=TZ)
start_utc=start_local.astimezone(timezone.utc)
end_utc=end_local.astimezone(timezone.utc)

flags=set()

def call_readings(cursor=None, limit=100):
    cmd=['meterctl','readings','--meter',METER,'--limit',str(limit)]
    if cursor is not None:
        cmd += ['--cursor', str(cursor)]
    while True:
        p=subprocess.run(cmd, capture_output=True, text=True)
        if p.returncode==3:
            flags.add('rate_limited')
            try:
                err=json.loads(p.stdout or p.stderr)
                wait=float(err.get('retry_after_s',1))
            except Exception:
                wait=1
            time.sleep(wait)
            continue
        if p.returncode!=0:
            raise RuntimeError(f'cmd failed {p.returncode}: {p.stdout} {p.stderr}')
        return json.loads(p.stdout)

def rec_end_utc(rec):
    if rec.get('v')==1:
        return datetime.fromisoformat(rec['ts'].replace('Z','+00:00')).astimezone(timezone.utc)
    if rec.get('v')==2:
        return datetime.fromtimestamp(rec['ts']/1000, tz=timezone.utc)
    raise ValueError('unknown record version')

def rec_kwh(rec):
    if rec.get('v')==1:
        return float(rec['kwh'])
    if rec.get('v')==2:
        return float(rec['wh'])/1000.0

cursor=None
seen=set()
total=0.0
in_range=0
out_after=0

while True:
    page=call_readings(cursor)
    recs=page['records']
    for rec in recs:
        key=(rec.get('v'), rec.get('ts'))
        if key in seen:
            continue
        seen.add(key)
        t=rec_end_utc(rec)
        if t<=start_utc:
            continue
        if t> end_utc:
            out_after += 1
            continue
        in_range += 1
        total += rec_kwh(rec)
    if not page.get('has_more') or page.get('next_cursor') is None:
        break
    cursor=page['next_cursor']

# check missing hours: expect 24*30 = 720 hours in Nov
expected=24*30
if in_range!=expected:
    flags.add(f'hour_count_{in_range}_expected_{expected}')

print(json.dumps({
    'total_kwh': total,
    'in_range_hours': in_range,
    'expected_hours': expected,
    'start_utc': start_utc.isoformat(),
    'end_utc': end_utc.isoformat(),
    'flags': sorted(flags),
}, indent=2))
